"""Canonical sample report factory — Issue #53.

This module is the single source of truth for ``tests/fixtures/static/sample_report.json``.
The JSON file is generated by calling ``build()`` and serialising with ``to_json()``.

To regenerate the file after a model change, run from the repo root:

    uv run python tests/fixtures/make_sample_report.py

The report represents a partial inspection of a plausible FastAPI project that
was originally scaffolded with Spawn but has since been partially modified.
It deliberately covers every required scenario:

  - detected          : direct file evidence (language, framework, tool, structure)
  - inferred          : indirect evidence with explicit basis (package_manager)
  - unknown           : ambiguous signal, cannot confirm or deny (dependency)
  - not_detected      : active negative with locations checked (ci)
  - not_checked       : analyzer skipped a subject due to prior error (container)
  - recoverable diag  : dependency analyzer hit a malformed optional file, continued
  - per-analyzer status: language=complete, tooling=complete, dependency=partial
  - overall status    : partial (because dependency is partial)
"""

from __future__ import annotations

from pathlib import Path

from spawn.inspection.models import (
    AnalyzerResult,
    AnalysisStatus,
    Diagnostic,
    DetectionState,
    Evidence,
    Finding,
    FindingCategory,
    InspectionReport,
    InspectionTarget,
    ProjectSummary,
    RepositoryStructure,
)
from spawn.inspection.serialization import to_json
from spawn.core.project import ProjectMetadata


# Fixed timestamp so the file is deterministic across regenerations.
FIXED_GENERATED_AT = "2026-10-14T10:00:00+00:00"

# Fictional but plausible project root (posix; cross-platform tests use
# the string value directly rather than a real path).
FIXED_TARGET_PATH = "/projects/acme-api"


def build() -> InspectionReport:
    """Construct and return the canonical sample InspectionReport.

    The findings are in canonical order: sorted ascending by
    (category.value, subject).  The analyzer_results are sorted ascending
    by analyzer_name.
    """

    # ------------------------------------------------------------------
    # Findings — one per required detection state, canonical order
    # ------------------------------------------------------------------

    # DETECTED: python via pyproject.toml requires-python
    f_language = Finding(
        category=FindingCategory.LANGUAGE,
        subject="python",
        detection_state=DetectionState.DETECTED,
        evidence=(
            Evidence(
                path="pyproject.toml",
                indicator="requires-python field",
                detail=">=3.12",
            ),
        ),
        detail=None,
    )

    # Framework analyzer output: a dependency-only INFERRED signal and a direct
    # DETECTED import signal.  The orchestrator keeps the highest state and
    # unions the evidence, so the aggregated finding is DETECTED.
    fw_import = Finding(
        category=FindingCategory.FRAMEWORK,
        subject="fastapi",
        detection_state=DetectionState.DETECTED,
        evidence=(
            Evidence(
                path="src/acme_api/main.py",
                indicator="static import/declaration for fastapi",
                detail=None,
            ),
        ),
        detail=None,
    )
    fw_dependency = Finding(
        category=FindingCategory.FRAMEWORK,
        subject="fastapi",
        detection_state=DetectionState.INFERRED,
        evidence=(
            Evidence(
                path="pyproject.toml",
                indicator="framework dependency declared in manifest",
                detail=None,
            ),
        ),
        detail="A framework dependency is declared, but no direct usage was found",
    )
    f_framework = Finding(
        category=FindingCategory.FRAMEWORK,
        subject="fastapi",
        detection_state=DetectionState.DETECTED,
        evidence=(fw_dependency.evidence[0], fw_import.evidence[0]),
        detail=None,
    )

    # DETECTED: fastapi declared in pyproject.toml (dependency analyzer)
    f_dep_fastapi = Finding(
        category=FindingCategory.DEPENDENCY,
        subject="fastapi",
        detection_state=DetectionState.DETECTED,
        evidence=(
            Evidence(
                path="pyproject.toml",
                indicator="fastapi in [project.dependencies]",
                detail="fastapi>=0.115.0",
            ),
        ),
        detail=None,
    )

    # INFERRED: uv as package manager from lockfile (no explicit uv config section)
    f_pkg_manager = Finding(
        category=FindingCategory.PACKAGE_MANAGER,
        subject="uv",
        detection_state=DetectionState.INFERRED,
        evidence=(
            Evidence(
                path="uv.lock",
                indicator="uv.lock lockfile present",
                detail=None,
            ),
        ),
        detail=(
            "uv.lock is present but no [tool.uv] section found in pyproject.toml; "
            "uv inferred as package manager from lockfile evidence alone"
        ),
    )

    # UNKNOWN: a dependency whose version constraint is dynamic and cannot be evaluated
    f_dep_unknown = Finding(
        category=FindingCategory.DEPENDENCY,
        subject="sqlalchemy",
        detection_state=DetectionState.UNKNOWN,
        evidence=(
            Evidence(
                path="setup.cfg",
                indicator="dynamic install_requires expression",
                detail=None,
            ),
        ),
        detail=(
            "setup.cfg contains a dynamic install_requires that references "
            "an external version file; static analysis cannot resolve the value"
        ),
    )

    # NOT_DETECTED: no CI configuration found; detail names every location checked
    f_ci = Finding(
        category=FindingCategory.CI,
        subject="github-actions",
        detection_state=DetectionState.NOT_DETECTED,
        evidence=(),
        detail=(
            "checked .github/workflows/*.yml, .github/workflows/*.yaml, "
            ".circleci/config.yml, .gitlab-ci.yml — none present"
        ),
    )

    # NOT_CHECKED: no diagnostic is claimed as the cause.  (The real tooling
    # analyzer emits not_checked only next to a fatal tooling.internal_error;
    # modelling that here would turn the tooling result into FAILED, which
    # test_inspection_sample.py pins as COMPLETE.)
    f_container = Finding(
        category=FindingCategory.CONTAINER,
        subject="docker",
        detection_state=DetectionState.NOT_CHECKED,
        evidence=(),
        detail="Container configuration was not examined for this report",
    )

    # DETECTED: spawn-generated structure marker
    f_structure = Finding(
        category=FindingCategory.STRUCTURE,
        subject="spawn-generated",
        detection_state=DetectionState.DETECTED,
        evidence=(
            Evidence(
                path=".spawn/meta.json",
                indicator=".spawn/meta.json present",
                detail=None,
            ),
        ),
        detail=None,
    )

    # DETECTED: pytest via pyproject.toml tool section
    f_pytest = Finding(
        category=FindingCategory.TOOL,
        subject="pytest",
        detection_state=DetectionState.DETECTED,
        evidence=(
            Evidence(
                path="pyproject.toml",
                indicator="[tool.pytest.ini_options] section",
                detail=None,
            ),
        ),
        detail=None,
    )

    # Canonical order: sorted by (category.value, subject)
    # ci < container < dependency < framework < language < package_manager < structure < tool
    findings = (
        f_ci,
        f_container,
        f_dep_fastapi,
        f_dep_unknown,
        f_framework,
        f_language,
        f_pkg_manager,
        f_structure,
        f_pytest,
    )

    # ------------------------------------------------------------------
    # Diagnostics — recoverable problem in the dependency analyzer
    # ------------------------------------------------------------------

    # The dependency analyzer successfully parsed pyproject.toml and setup.cfg,
    # but requirements.txt was malformed (truncated mid-file).  It emitted a
    # non-fatal diagnostic and continued — hence status=partial, not failed.
    dep_diagnostic = Diagnostic(
        code="dependency.malformed_manifest",
        message=(
            "requirements.txt is truncated and could not be fully parsed; "
            "partial dependency list from this file may be missing"
        ),
        severity="warning",
        source="dependency",
        path="requirements.txt",
        fatal=False,
    )

    # ------------------------------------------------------------------
    # Analyzer results — sorted by analyzer_name
    # ------------------------------------------------------------------

    result_dependency = AnalyzerResult(
        analyzer_name="dependency",
        status=AnalysisStatus.PARTIAL,  # ran but hit a non-fatal diagnostic
        findings=(f_dep_fastapi, f_dep_unknown, f_pkg_manager),
        diagnostics=(dep_diagnostic,),
    )

    result_framework = AnalyzerResult(
        analyzer_name="framework",
        status=AnalysisStatus.COMPLETE,
        findings=(fw_dependency, fw_import),
        diagnostics=(),
    )

    result_language = AnalyzerResult(
        analyzer_name="language",
        status=AnalysisStatus.COMPLETE,
        findings=(f_language,),
        diagnostics=(),
    )

    result_tooling = AnalyzerResult(
        analyzer_name="tooling",
        status=AnalysisStatus.COMPLETE,
        findings=(f_ci, f_container, f_structure, f_pytest),
        diagnostics=(),
    )

    # Canonical order: sorted by analyzer_name
    analyzer_results = (
        result_dependency,
        result_framework,
        result_language,
        result_tooling,
    )

    # ------------------------------------------------------------------
    # Recorded metadata from .spawn/meta.json
    # ------------------------------------------------------------------

    recorded_metadata = ProjectMetadata(
        intent="backend-api",
        framework="fastapi",
        provider=None,
        spawn_version="1.0.9",
        created_at="2026-01-01T00:00:00+00:00",
        generator="blueprint",
        git=True,
        uv=True,
        source=None,
    )

    # ------------------------------------------------------------------
    # Project summary and repository structure
    # ------------------------------------------------------------------

    summary = ProjectSummary(
        name="acme-api",
        origin="spawn",
        spawn_version="1.0.9",
        primary_language="python",
        primary_framework="fastapi",
    )

    structure = RepositoryStructure(
        top_level_files=(
            ".gitignore",
            "AGENTS.md",
            "CHANGELOG.md",
            "LICENSE",
            "README.md",
            "pyproject.toml",
            "requirements.txt",
            "setup.cfg",
            "uv.lock",
        ),
        top_level_directories=(".spawn", "src", "tests"),
        file_count=25,
        directory_count=4,
    )

    # ------------------------------------------------------------------
    # Report
    # ------------------------------------------------------------------

    return InspectionReport(
        target=InspectionTarget(path=Path(FIXED_TARGET_PATH)),
        status=AnalysisStatus.PARTIAL,  # partial because dependency analyzer is partial
        generated_at=FIXED_GENERATED_AT,
        recorded_metadata=recorded_metadata,
        summary=summary,
        structure=structure,
        findings=findings,
        analyzer_results=analyzer_results,
        diagnostics=(),  # no report-level diagnostics
    )


if __name__ == "__main__":
    import sys
    from pathlib import Path as _Path

    out = _Path(__file__).parent / "static" / "sample_report.json"
    out.write_text(to_json(build()), encoding="utf-8")
    print(f"Written {out}", file=sys.stderr)
